class Solution:
    def maxSum(self, nums, k, m):
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums): pre[i + 1] = pre[i] + x
        NEG = float('-inf')
        dp = [[0] * (k + 1) for _ in range(n + 2)]
        ext = [[NEG] * (k + 1) for _ in range(n + 2)]
        for i in range(n - 1, -1, -1):
            for kk in range(1, k + 1):
                e = NEG
                if i + m <= n:
                    e = pre[i + m] - pre[i] + dp[i + m][kk - 1]
                if ext[i + 1][kk] > NEG:
                    e = max(e, nums[i] + ext[i + 1][kk])
                ext[i][kk] = e
                dp[i][kk] = max(dp[i + 1][kk], e)
        return dp[0][k]

