class Solution {
    public int maxSum(int[] nums, int k, int m) {
        int n = nums.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        long NEG = Long.MIN_VALUE / 2;
        long[][] dp = new long[n + 2][k + 1];
        long[][] ext = new long[n + 2][k + 1];
        for (long[] r : ext) Arrays.fill(r, NEG);
        for (int i = n - 1; i >= 0; i--) {
            for (int kk = 1; kk <= k; kk++) {
                long e = NEG;
                if (i + m <= n) e = pre[i + m] - pre[i] + dp[i + m][kk - 1];
                e = Math.max(e, nums[i] + ext[i + 1][kk]);
                ext[i][kk] = e;
                dp[i][kk] = Math.max(dp[i + 1][kk], e);
            }
        }
        return (int) dp[0][k];
    }
}

