var maxSum = function(nums, k, m) {
    const n = nums.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    const NEG = -Infinity;
    const dp = Array.from({length: n + 2}, () => new Array(k + 1).fill(0));
    const ext = Array.from({length: n + 2}, () => new Array(k + 1).fill(NEG));
    for (let i = n - 1; i >= 0; i--) {
        for (let kk = 1; kk <= k; kk++) {
            let e = NEG;
            if (i + m <= n) e = pre[i + m] - pre[i] + dp[i + m][kk - 1];
            e = Math.max(e, nums[i] + ext[i + 1][kk]);
            ext[i][kk] = e;
            dp[i][kk] = Math.max(dp[i + 1][kk], e);
        }
    }
    return dp[0][k];
};
